-- أكواد التحديد (Tahdit) وقرارات منع الدخول: كيف تعرف أنّ لديك كوداً وكيف تعترض — المهل الحقيقية
INSERT INTO articles (id, slug, title, category, intro, details, documents, steps, tips, fees, warning, source, seo_title, seo_description, seo_keywords, tags, status, active, published_at, last_update)
VALUES (
  $$tahdit-entry-restriction-codes-how-to-object$$,
  $$tahdit-entry-restriction-codes-how-to-object$$,
  $$أكواد التحديد (Tahdit) وقرارات منع الدخول: كيف تعرف أنّ لديك كوداً وكيف تعترض — المهل الحقيقية$$,
  $$الكملك والحماية المؤقتة$$,
  $$«التحديد» (Tahdit) قيدٌ أو سجلٌّ إداري يُوضَع على الأجنبي في أنظمة الدولة، وقد يعني منع الدخول إلى تركيا أو سبباً مرتبطاً بالترحيل، وغالباً لا تعرف بوجوده إلا عند رفض دخولك على الحدود أو أثناء معاملة رسمية. في هذا الدليل نشرح كيف تتحقّق إن كان لديك كود تحديد، وما هي المهل الحقيقية للاعتراض — مع تصحيح الخرافة الشائعة عن «مهلة 30 يوماً» — دون أن نعِدك بقائمة مؤكّدة لمعاني الأكواد لأنها غير منشورة رسمياً وتحتاج تأكيداً من الجهة المختصة أو محامٍ.$$,
  $$<p>إذا رُفض دخولك إلى تركيا فجأة، أو تعطّلت معاملة إقامة أو مراجعة رسمية بلا سبب واضح، فقد يكون على ملفّك ما يُسمّى <strong>«كود تحديد» (Tahdit Kodu)</strong>. التحديد هو قيدٌ إداري يُدرَج في أنظمة الدولة على اسم الأجنبي، وقد يشير إلى <strong>منع دخول</strong> أو إلى سببٍ متعلّق بالترحيل. المشكلة أنّ كثيرين لا يكتشفون وجوده إلا متأخراً — عند الحدود أو أمام موظّف — لأنّه لا يصلك دائماً إشعارٌ استباقي به.</p>

<h2>كيف تعرف أنّ لديك كود تحديد؟</h2>
<p>لا توجد طريقة واحدة مضمونة تكشف كل الأكواد، لكن هذه أكثر المسارات موثوقية:</p>
<ul>
<li><strong>مراجعة إدارة الهجرة (Göç İdaresi / PMM):</strong> اسأل عن حالتك مباشرة لدى مديرية الهجرة في ولايتك؛ فهي الجهة التي تضع القيد وتملك تفصيله.</li>
<li><strong>التحقّق عبر e-Devlet:</strong> بعض القيود أو حالات المنع قد تظهر ضمن سجلّك على البوابة الحكومية، لكن ليست كلها تظهر هناك، فغياب أي إشارة لا يعني بالضرورة خلوّ ملفّك.</li>
<li><strong>الاستعانة بمحامٍ مختص:</strong> المحامي يستطيع الاستعلام رسمياً ومعرفة نوع القيد وسببه بدقّة أكبر، وهو المسار الأنسب في الحالات الحسّاسة.</li>
</ul>

<h2>ماذا تعني الأكواد؟ ولماذا لا ننشر «قاموساً» لها</h2>
<p>تتداول مواقع كثيرة قوائم لمعاني الأكواد، لكنّ المعاني الكاملة والدقيقة <strong>ليست منشورة كقائمة رسمية أولية من الجهة الحكومية</strong>. لذلك نتجنّب هنا نشر قاموسٍ واثق قد يضلّلك؛ والصحيح أن تؤكّد معنى كودك تحديداً لدى إدارة الهجرة أو عبر محامٍ مختص.</p>
<p>ولتوضيح الفكرة بمثال واحد فقط: الكود <strong>V-84</strong> كان يوضَع على من دخلوا البلاد بشرط استخراج إقامة خلال 10 أيام ولم يلتزموا بذلك — وهذه ممارسة <strong>انتهى العمل بها في 09.06.2020</strong>، أي إنّها لم تعد تُطبَّق على الحالات الجديدة. هذا يوضّح لماذا لا يصحّ الاعتماد على قوائم قديمة متداولة قد تكون تجاوزها الزمن.</p>

<h2>المهل الحقيقية للاعتراض — صحّح المعلومة</h2>
<p>هنا أخطر نقطة يقع فيها الناس. تنتشر خرافة أنّ «مهلة الاعتراض 30 يوماً»، وهذا <strong>غير صحيح</strong> كمهلة للطعن القضائي. إليك الصورة الدقيقة:</p>
<ul>
<li><strong>دعوى إلغاء القرار الإداري (منع الدخول / كود التحديد):</strong> تُرفع أمام <strong>المحكمة الإدارية (İdare Mahkemesi)</strong> خلال <strong>60 يوماً</strong> من تاريخ التبليغ بالقرار، وغالباً تكون المحكمة المختصة في أنقرة أو في مكان الجهة التي أصدرت الإجراء.</li>
<li><strong>قرار الترحيل (Sınır Dışı / الترحيل الإداري):</strong> له مهلة منفصلة وأقصر — <strong>7 أيام فقط</strong> من التبليغ لرفع الاعتراض أمام المحكمة الإدارية، وهذه مهلة مُسقِطة للحق إن فاتت. راجع تفاصيل هذا المسار في مقالنا حول <a href="/article/deportation-rights">حقوقك عند قرار الترحيل</a>.</li>
<li><strong>«الـ 30 يوماً» من أين جاءت؟</strong> هي في الأصل <strong>مدة ردّ الجهة الإدارية</strong> على طلب تظلّم إداري اختياري تقدّمه أنت قبل الدعوى، وهذا التظلّم — إن قدّمته — <strong>يوقف احتساب مهلة الـ 60 يوماً</strong>. فهي ليست مهلة الطعن الخاصة بك، بل مهلة استجابة الإدارة.</li>
</ul>
<p>الخلاصة العملية: لا تربط قرارك بمهلة الثلاثين يوماً؛ احسب من <strong>تاريخ التبليغ</strong>، وإن كان لديك قرار ترحيل فتصرّف خلال <strong>7 أيام</strong> فوراً، وإلا فالإطار العام لإلغاء القرار الإداري هو <strong>60 يوماً</strong>.</p>

<h2>خطوات عملية بهدوء</h2>
<ul>
<li>احتفظ بأيّ ورقة أو تبليغ استلمته، ودوّن <strong>تاريخ التبليغ</strong> بدقّة لأنه يبدأ منه احتساب المهلة.</li>
<li>استعلم عن نوع الكود وسببه لدى إدارة الهجرة أو عبر محامٍ قبل أن تبني قرارك.</li>
<li>إن كان الأمر قرار ترحيل، لا تنتظر — المهلة 7 أيام فقط.</li>
<li>يمكنك تقديم تظلّم إداري اختياري إلى إدارة الهجرة، مع الانتباه إلى أثره على المهل، أو التوجّه مباشرةً إلى الدعوى القضائية.</li>
</ul>

<p>القيود المتعلّقة بالدخول والترحيل مصيرية، وأيّ خطأ في الحساب قد يُسقط حقّك. للاطّلاع على سياقات مرتبطة يفيدك مقالنا عن <a href="/article/return-code-v87">كود العودة V-87</a> ومقالنا عن <a href="/article/deportation-centers-rights">حقوقك داخل مراكز الترحيل</a>. وفي كل الأحوال، تحقّق رسمياً من الجهة المختصة قبل اتخاذ أي إجراء.</p>$$,
  ARRAY[
    $$نسخة من التبليغ أو القرار الإداري الذي استلمته (إن وُجد)$$,
    $$جواز السفر أو وثيقة الهوية / بطاقة الحماية المؤقتة (Kimlik)$$,
    $$أي أوراق تثبّت تاريخ التبليغ (المظروف، وصل الاستلام)$$,
    $$توكيل لمحامٍ في حال متابعة الدعوى قضائياً$$
  ]::text[],
  ARRAY[
    $$دوّن تاريخ التبليغ بدقّة، فمنه تبدأ المهلة (7 أيام للترحيل / 60 يوماً لإلغاء القرار الإداري).$$,
    $$استعلم عن حالتك ونوع الكود لدى إدارة الهجرة (Göç İdaresi) أو عبر e-Devlet أو محامٍ مختص.$$,
    $$حدّد نوع القرار: قرار ترحيل (Sınır Dışı) أم قيد/منع دخول (Tahdit)، لأنّ المهلة تختلف جذرياً.$$,
    $$إن رغبت، قدّم تظلّماً إدارياً اختيارياً إلى إدارة الهجرة مع الانتباه إلى أثره في إيقاف مهلة الـ 60 يوماً.$$,
    $$ارفع دعوى الإلغاء أمام المحكمة الإدارية (İdare Mahkemesi) ضمن المهلة الصحيحة، ويُفضّل بطلب وقف التنفيذ.$$,
    $$تابع القرار القضائي، ولا تتأخّر خصوصاً في قرارات الترحيل ذات المهلة القصيرة.$$
  ]::text[],
  ARRAY[
    $$لا تصدّق خرافة «مهلة 30 يوماً» للطعن؛ فهي مدة ردّ الإدارة على التظلّم الاختياري وليست مهلتك للطعن القضائي.$$,
    $$قرار الترحيل مهلته 7 أيام فقط وهي مُسقِطة للحق — تصرّف فوراً.$$,
    $$لا تعتمد على قوائم أكواد قديمة متداولة على الإنترنت؛ بعضها لم يعد سارياً مثل V-84 الذي انتهى العمل به في 09.06.2020.$$,
    $$احتفظ بالمظروف ووصل التبليغ لأنّ تاريخ التبليغ هو نقطة البداية لاحتساب كل المهل.$$,
    $$في الحالات الحسّاسة، الاستعانة بمحامٍ مختص بقانون الأجانب أفضل بكثير من الاجتهاد الفردي.$$
  ]::text[],
  $$تختلف الرسوم القضائية وأتعاب المحاماة حسب المحكمة والولاية ونوع الدعوى؛ لا توجد قيمة ثابتة، لذا تحقّق منها رسمياً أو استفسر من محامٍ قبل رفع الدعوى.$$,
  $$هذا المقال إرشادي عام وليس استشارة قانونية؛ قرارات منع الدخول والترحيل مصيرية والمهل قصيرة ومُسقِطة للحق، لذا تحقّق دائماً من الجهة الرسمية (إدارة الهجرة) واستعن بمحامٍ مختص قبل اتخاذ أي إجراء.$$,
  $$https://www.goc.gov.tr , https://www.mevzuat.gov.tr$$,
  $$أكواد التحديد (Tahdit) ومنع الدخول في تركيا: المهل الحقيقية للاعتراض$$,
  $$كيف تعرف أنّ لديك كود تحديد (Tahdit) أو قرار منع دخول في تركيا، والمهل الحقيقية للاعتراض: 60 يوماً لإلغاء القرار الإداري و7 أيام للترحيل — مع تصحيح خرافة الـ 30 يوماً.$$,
  ARRAY[
    $$كود التحديد$$,
    $$Tahdit$$,
    $$منع الدخول تركيا$$,
    $$قرار الترحيل$$,
    $$الاعتراض على منع الدخول$$,
    $$المحكمة الإدارية$$,
    $$إدارة الهجرة$$,
    $$V-84$$,
    $$غوتش إداره سي$$,
    $$giriş yasağı$$
  ]::text[],
  ARRAY[
    $$residence$$,
    $$deportation$$,
    $$immigration$$,
    $$entry-ban$$,
    $$legal$$,
    $$protection$$
  ]::text[],
  'pending', true, '2026-06-29', '2026-06-29'
) ON CONFLICT (id) DO NOTHING;

-- إجازة الأمومة في تركيا (Analık İzni): 16 أسبوعاً — و18 للحمل المتعدّد
INSERT INTO articles (id, slug, title, category, intro, details, documents, steps, tips, fees, warning, source, seo_title, seo_description, seo_keywords, tags, status, active, published_at, last_update)
VALUES (
  $$maternity-leave-turkey-analik-izni$$,
  $$maternity-leave-turkey-analik-izni$$,
  $$إجازة الأمومة في تركيا (Analık İzni): 16 أسبوعاً — و18 للحمل المتعدّد$$,
  $$الصحة والتأمين$$,
  $$تمنح المرأة العاملة في تركيا إجازة أمومة قانونية مدفوعة مدتها 16 أسبوعاً بحسب قانون العمل رقم 4857 (المادة 74): 8 أسابيع قبل الولادة و8 أسابيع بعدها. وفي حالة الحمل المتعدّد (توأم فأكثر) تُضاف أسبوعان إلى فترة ما قبل الولادة فتصبح المدة الإجمالية 18 أسبوعاً. يوضّح هذا الدليل حقوق الأم العاملة كاملةً: نقل جزء من إجازة ما قبل الولادة إلى ما بعدها، الإجازة غير المدفوعة حتى 6 أشهر، ساعة الرضاعة (süt izni)، وبدل العجز المؤقت الذي تدفعه مؤسسة الضمان الاجتماعي (SGK) عند استيفاء الشروط.$$,
  $$<p>إجازة الأمومة (Analık İzni) حقٌّ قانوني ثابت لكل امرأة عاملة خاضعة لقانون العمل التركي رقم 4857، وتحديداً <strong>المادة 74</strong>. الهدف منها حماية الأم والجنين والطفل خلال المرحلة الأكثر حساسية. في هذا الدليل نشرح المدد بدقّة، والخيارات المتاحة لكِ، وكيف يرتبط ذلك ببدل مؤسسة الضمان الاجتماعي (SGK).</p>

<h2>كم تبلغ مدة إجازة الأمومة؟</h2>
<p>القاعدة الأساسية واضحة: <strong>16 أسبوعاً</strong> إجمالاً، موزّعة على النحو التالي:</p>
<ul>
<li><strong>8 أسابيع قبل الولادة</strong> (فترة ما قبل الولادة / doğum öncesi).</li>
<li><strong>8 أسابيع بعد الولادة</strong> (فترة ما بعد الولادة / doğum sonrası).</li>
</ul>
<p>هذه المدة مخصّصة للحمل الفردي (طفل واحد)، ولا يجوز تشغيل المرأة العاملة خلالها.</p>

<h2>الحمل المتعدّد (توأم فأكثر): 18 أسبوعاً</h2>
<p>عند الحمل المتعدّد تُضاف <strong>أسبوعان</strong> إلى فترة <strong>ما قبل الولادة</strong> تحديداً، فتصبح المدد:</p>
<ul>
<li><strong>10 أسابيع قبل الولادة</strong> (8 + 2).</li>
<li><strong>8 أسابيع بعد الولادة</strong> (تبقى كما هي).</li>
<li>المجموع: <strong>18 أسبوعاً</strong>.</li>
</ul>
<p>انتبهي: الأسبوعان الإضافيان يُضافان إلى ما <em>قبل</em> الولادة، وليسا بعدها — لذلك المجموع في الحمل المتعدّد هو 18 أسبوعاً وليس 16.</p>

<h2>هل يمكنني العمل حتى قرب موعد الولادة؟</h2>
<p>نعم، بشرط. إذا كانت حالتكِ الصحية جيّدة و<strong>وافق الطبيب</strong> على ذلك، يجوز لكِ الاستمرار في العمل حتى <strong>3 أسابيع قبل الولادة</strong>. في هذه الحالة يُمكن <strong>نقل الأسابيع المتبقّية من فترة ما قبل الولادة إلى ما بعد الولادة</strong>، بحيث تقضين وقتاً أطول مع طفلكِ بعد الوضع دون أن تخسري من إجمالي رصيد الإجازة. يتطلّب ذلك تقريراً طبياً يثبت أنّ متابعة العمل لا تضرّ بكِ ولا بالجنين.</p>

<h2>ماذا بعد انتهاء الإجازة المدفوعة؟</h2>
<p>بعد انتهاء إجازة الأمومة المدفوعة، يحقّ للأم أن تطلب:</p>
<ul>
<li><strong>إجازة غير مدفوعة (ücretsiz izin) حتى 6 أشهر</strong> لرعاية الطفل. هذه الفترة لا يُدفع خلالها أجر، لكنها تحفظ لكِ وظيفتكِ.</li>
<li><strong>ساعة الرضاعة (süt izni):</strong> يحقّ للأم <strong>ساعة ونصف يومياً</strong> للرضاعة حتى يُتمّ الطفل <strong>عامه الأول</strong>، وتحدّد الأم بنفسها توقيت هذه الفترة وطريقة تقسيمها، وتُحتسب ضمن ساعات العمل اليومية.</li>
</ul>

<h2>بدل الضمان الاجتماعي (SGK) خلال الإجازة</h2>
<p>خلال إجازة الأمومة قد تدفع مؤسسة الضمان الاجتماعي <strong>بدل العجز المؤقت عن العمل</strong> (geçici iş göremezlik ödeneği، ويُعرف بـ «işgörmezlik») إذا استوفت الأم شروط عدد أيام التأمين المطلوبة. تختلف هذه الشروط (عدد الأيام المدفوعة قبل الولادة) وقد تتغيّر من سنة لأخرى، لذا <strong>تحقّقي من SGK</strong> بشأن أهليتكِ ومقدار البدل عبر بوابة e-Devlet أو أقرب مديرية للضمان الاجتماعي قبل الاعتماد على أي رقم. البدل يُصرف عن أيام التقرير الطبي (istirahat) ولا يُصرف تلقائياً دون استيفاء الشروط.</p>

<h2>نصيحة عملية</h2>
<p>احتفظي بنسخ من التقارير الطبية وإشعار الولادة، وبلّغي صاحب العمل خطّياً بموعد بدء الإجازة. لتنظيم أوراق الطفل بعد الولادة (قيد المواليد والحصول على الرقم) راجعي دليلنا: <a href="/article/family-birth-registration-flow">تسجيل المواليد الجدد وإجراءات القيد</a>.</p>

<p><strong>تنبيه:</strong> المدد المذكورة أعلاه (16 و18 أسبوعاً) ثابتة في نصّ المادة 74 من قانون العمل 4857، أمّا شروط بدل SGK ومقاديره فمتغيّرة — تحقّقي منها رسمياً قبل اتخاذ أي قرار.</p>$$,
  ARRAY[
    $$تقرير طبي يثبت الحمل وموعد الولادة المتوقّع (للحصول على الإجازة وتحديد بدايتها)$$,
    $$إشعار/شهادة الولادة (doğum belgesi) بعد الوضع$$,
    $$تقرير طبي بموافقة الطبيب إذا رغبتِ بالعمل حتى 3 أسابيع قبل الولادة$$,
    $$طلب خطّي يُقدَّم لصاحب العمل بموعد بدء الإجازة$$
  ]::text[],
  ARRAY[
    $$راجعي الطبيب واحصلي على تقرير يحدّد موعد الولادة المتوقّع لبدء احتساب فترة الـ8 أسابيع قبل الولادة (أو 10 أسابيع في الحمل المتعدّد).$$,
    $$بلّغي صاحب العمل خطّياً بموعد بدء الإجازة وأرفقي التقرير الطبي.$$,
    $$إن رغبتِ بالعمل حتى 3 أسابيع قبل الولادة، احصلي على موافقة الطبيب واطلبي نقل الأسابيع المتبقّية إلى ما بعد الولادة.$$,
    $$بعد الولادة، سلّمي إشعار/شهادة الولادة لتثبيت فترة الـ8 أسابيع اللاحقة.$$,
    $$تحقّقي من SGK عبر e-Devlet بشأن أهليتكِ لبدل العجز المؤقت (işgörmezlik) وطريقة صرفه.$$,
    $$عند انتهاء الإجازة المدفوعة، قدّمي طلباً بالإجازة غير المدفوعة (حتى 6 أشهر) إن رغبتِ، ونظّمي ساعة الرضاعة اليومية مع صاحب العمل.$$
  ]::text[],
  ARRAY[
    $$الأسبوعان الإضافيان في الحمل المتعدّد يُضافان إلى فترة ما قبل الولادة — المجموع 18 أسبوعاً وليس 16.$$,
    $$نقل جزء من إجازة ما قبل الولادة إلى ما بعدها يتطلّب موافقة الطبيب وحالة صحية جيّدة.$$,
    $$ساعة الرضاعة (ساعة ونصف يومياً) حقّ حتى يُتمّ الطفل عامه الأول، وتُحتسب ضمن ساعات العمل.$$,
    $$الإجازة غير المدفوعة (حتى 6 أشهر) تحفظ وظيفتكِ لكنها بلا أجر — خطّطي لها مالياً.$$,
    $$لا تعتمدي على رقم ثابت لبدل SGK؛ الشروط والمقادير تتغيّر — راجعي المؤسسة رسمياً.$$
  ]::text[],
  $$لا رسوم للحصول على إجازة الأمومة نفسها فهي حقّ قانوني. أمّا بدل العجز المؤقت (işgörmezlik) فتُحسب قيمته وفق كسبكِ وأيام التقرير الطبي وتتغيّر سنوياً — تحقّقي من SGK.$$,
  $$هذا المحتوى إرشادي وليس استشارة قانونية. المدد (16 و18 أسبوعاً) ثابتة في المادة 74 من قانون العمل 4857، لكن شروط بدل SGK ومقاديره متغيّرة سنوياً — تحقّقي رسمياً من مؤسسة الضمان الاجتماعي (SGK) وصاحب العمل قبل اتخاذ أي قرار يمسّ دخلكِ أو وظيفتكِ.$$,
  $$İş Kanunu 4857 Madde 74: https://www.mevzuat.gov.tr/mevzuatmetin/1.5.4857.pdf , SGK: https://www.sgk.gov.tr$$,
  $$إجازة الأمومة في تركيا (Analık İzni): 16 و18 أسبوعاً — دليل قانون العمل 4857$$,
  $$دليل إجازة الأمومة في تركيا وفق قانون العمل 4857 (المادة 74): 16 أسبوعاً (8 قبل و8 بعد الولادة)، و18 أسبوعاً للحمل المتعدّد، مع ساعة الرضاعة والإجازة غير المدفوعة وبدل SGK.$$,
  ARRAY[
    $$إجازة الأمومة في تركيا$$,
    $$Analık İzni$$,
    $$إجازة الولادة تركيا$$,
    $$قانون العمل 4857$$,
    $$المادة 74$$,
    $$ساعة الرضاعة$$,
    $$süt izni$$,
    $$الحمل المتعدد إجازة$$,
    $$بدل العجز المؤقت$$,
    $$SGK إجازة الأمومة$$
  ]::text[],
  ARRAY[
    $$health$$,
    $$insurance$$,
    $$maternity-leave$$,
    $$labor-law$$,
    $$sgk$$,
    $$women$$,
    $$work$$
  ]::text[],
