-- YKS أم YÖS؟ أيّ امتحان جامعي يخصّك — يُحدّده مكان دراستك الثانوية لا جنسيتك (2026)
INSERT INTO articles (id, slug, title, category, intro, details, documents, steps, tips, fees, warning, source, seo_title, seo_description, seo_keywords, tags, status, active, published_at, last_update)
VALUES (
  $$yks-vs-yos-placement-by-schooling-2026$$,
  $$yks-vs-yos-placement-by-schooling-2026$$,
  $$YKS أم YÖS؟ أيّ امتحان جامعي يخصّك — يُحدّده مكان دراستك الثانوية لا جنسيتك (2026)$$,
  $$التعليم والجامعات$$,
  $$كثيرون يظنّون أنّ الجنسية هي التي تُحدّد امتحان الجامعة في تركيا، والصحيح أنّ ما يُحدّده هو مكان إنهاء الثانوية: داخل تركيا أم خارجها. مَن أنهى ثانويته داخل تركيا في مدرسة تركية رسمية يدخل عبر YKS مثل الأتراك، ومَن أنهاها خارج تركيا يدخل عبر YÖS / TR-YÖS بحصص كل جامعة. في هذا الدليل نشرح القاعدة الجديدة لعام 2026، والاستثناءات المهمّة التي تُبقي بعض طلاب الداخل مؤهّلين لـ YÖS، ونافذة الانتقال بدقّة سنة التسجيل.$$,
  $$<h2>القاعدة الأساسية: مكان الدراسة الثانوية لا الجنسية</h2><p>الخطأ الأشيع بين الطلاب العرب والسوريين في تركيا هو الاعتقاد بأنّ الجنسية تُحدّد أيّ امتحان جامعي يخصّهم. الحقيقة أنّ المعيار الحاسم بحسب أسس قبول الطلبة من الخارج التي يُصدرها مجلس التعليم العالي (YÖK - «Yurt Dışından Öğrenci Kabulüne İlişkin Esaslar») هو مكان إتمام الدراسة الثانوية: داخل تركيا أم خارجها. لا يوجد شرط جنسية تركية للتقدّم لامتحان YKS؛ الأجنبي الذي أنهى ثانويته داخل تركيا يدخل عبر YKS مثله مثل المواطن التركي تماماً.</p><p>باختصار: مَن أتمّ الثانوية داخل تركيا في مدرسة تركية رسمية يتقدّم لامتحان YKS الذي تديره مؤسسة القياس (ÖSYM). ومَن أتمّ ثانويته خارج تركيا يتقدّم عبر مسار الطلبة من الخارج (YÖS / TR-YÖS)، وهو مسار تُنظّم كلّ جامعة فيه امتحانها الخاص أو حصصها الخاصة (kontenjan) وشروط قبولها.</p><h2>تغيير 2026 المهم</h2><p>طرأ تعديل جوهري اعتباراً من 2026: الطلاب من حَمَلة الجنسيات الأجنبية الذين درسوا أو تخرّجوا من الثانوية داخل تركيا لم يعودوا يُقبَلون ضمن حصص «القبول من الخارج» (YÖS / TR-YÖS)، وصار عليهم التقدّم لامتحان YKS كغيرهم من خرّيجي الثانويات التركية. أي أنّ الطالب الأجنبي الذي أنهى ثانويته في مدرسة تركية داخل تركيا صار مساره الطبيعي هو YKS لا YÖS.</p><h2>استثناءات مهمة تُبقي طلاب الداخل مؤهّلين لـ YÖS</h2><p>هذه أهمّ نقطة في المقال، وإغفالها يُوقع الطالب في خطأ مصيري. رغم القاعدة أعلاه، تبقى فئات تدرس فعلياً داخل تركيا لكنها ما زالت مؤهّلة للتقدّم عبر مسار الطلبة من الخارج (YÖS / TR-YÖS)، وهي بحسب صياغة الأسس الرسمية:</p><ul><li>طلاب مدارس السفارات والبعثات (elçilik okulları / sefaret okulları) داخل تركيا.</li><li>طلاب المدارس الخاصة الدولية المُدرَجة في نظام MOBIS (MOBIS sisteminde yer alan Milletlerarası özel öğretim kurumları).</li><li>الطلاب الذين جرى إحضارهم ضمن مشروع تديره وزارة التربية الوطنية (MEB) أو مجلس التعليم العالي (YÖK).</li></ul><p>هؤلاء يبقون مؤهّلين لـ YÖS / TR-YÖS رغم أنّهم موجودون جسدياً داخل تركيا. لولا هذا الاستثناء لقيل لطالب مدرسة سفارة أو مدرسة دولية مسجّلة في MOBIS خطأً إنّ YKS مساره الوحيد، وهذا غير صحيح. إن كنت في إحدى هذه المدارس فتحقّق رسمياً من دليل الجامعة التي تستهدفها ومن أسس YÖK السارية قبل أن تبني قرارك، فالقوائم والشروط تُراجَع سنوياً.</p><h2>نافذة الانتقال بدقّة: سنة التسجيل هي الفيصل</h2><p>لتفادي الغموض حول «الدفعات القديمة»، القاعدة الدقيقة أنّ العامل الحاسم هو سنة التسجيل في المدرسة الثانوية التركية، والحدّ الفاصل هو العام الدراسي 2022-2023. مَن سُجِّل في ثانوية تركية قبل العام الدراسي 2022-2023 كان بإمكانه استخدام كلا المسارين (YÖS وYKS) حتى عام 2025، ثم صار مقتصراً على YKS فقط اعتباراً من 2026. أمّا مَن سُجِّل اعتباراً من العام الدراسي 2022-2023 فصاعداً فمساره هو YKS فقط. ولأنّ هذه التفاصيل تُحدَّث دورياً، تحقّق رسمياً من دليل ÖSYM / YÖK الحالي قبل اتخاذ أيّ قرار.</p><h2>معادلة الشهادة (Denklik) متى تلزم؟</h2><p>معادلة الشهادة الثانوية (Denklik) من وزارة التربية الوطنية (MEB) تلزم فقط للشهادات الصادرة عن أنظمة تعليمية غير تركية، أي لمن أنهى ثانويته خارج المنظومة التركية. أمّا خرّيج الثانوية التركية الرسمية فلا يحتاج معادلة لأنّ شهادته تركية أصلاً. لتفاصيل المعادلة راجع دليلنا: <a href="/article/highschool-denklik">معادلة الشهادة الثانوية</a>.</p><h2>مراحل YKS وبدائل TR-YÖS</h2><p>امتحان YKS يتكوّن من مراحل: الاختبار الأساسي (TYT)، والاختبار الميداني (AYT)، واختبار اللغة الأجنبية (YDT) لمن يحتاجه. أمّا في مسار الطلبة من الخارج فتُدير مؤسسة القياس امتحان TR-YÖS الموحّد، كما تقبل بعض الجامعات نتائج امتحانات دولية بديلة مثل SAT أو Abitur أو IB وفق شروط كلّ جامعة. لتفاصيل مسار YÖS راجع: <a href="/article/yos-exam-guide">دليل امتحان اليوس (YÖS)</a>، ولما بعد النتيجة راجع: <a href="/article/after-yos-turkey-university-tercih-application-registration-2026">بعد اليوس: التفضيل والتقديم والتسجيل في الجامعة (2026)</a>.</p><h2>خلاصة عملية</h2><p>اسأل نفسك سؤالاً واحداً: أين أنهيتُ الثانوية؟ إن كان داخل تركيا في مدرسة تركية رسمية فمسارك YKS (إلّا إن كنت ضمن استثناءات مدارس السفارات أو مدارس MOBIS الدولية أو مشروع MEB/YÖK). وإن كان خارج تركيا فمسارك YÖS / TR-YÖS. الحصص والشروط ومواعيد التقديم تختلف بين الجامعات وتتغيّر سنوياً، لذلك تحقّق رسمياً من دليل الجامعة ومن أسس YÖK وÖSYM الحالية قبل أيّ خطوة.$$,
  ARRAY[
    $$الشهادة الثانوية (تركية للمسار YKS، أو أجنبية مع معادلة MEB للمسار YÖS)$$,
    $$معادلة الشهادة الثانوية (Denklik) من وزارة التربية الوطنية MEB — للشهادات غير التركية فقط$$,
    $$جواز سفر ساري أو بطاقة إقامة / حماية مؤقتة (الكملك)$$,
    $$وثيقة تُثبت مكان إتمام الثانوية (شهادة التخرّج / كشف العلامات)$$,
    $$إثبات القيد للمسجَّلين في مدارس السفارات أو المدارس الدولية MOBIS أو مشروع MEB/YÖK (لمن يستند إلى الاستثناء)$$,
    $$نتيجة الامتحان المطلوب: YKS (TYT/AYT/YDT) أو TR-YÖS، أو نتيجة امتحان دولي بديل مقبول (SAT / Abitur / IB) حسب الجامعة$$
  ]::text[],
  ARRAY[
    $$حدّد أولاً أين أنهيت ثانويتك: داخل تركيا في مدرسة تركية رسمية، أم خارج تركيا$$,
    $$إن أنهيتها داخل تركيا في مدرسة تركية رسمية فمسارك YKS (TYT/AYT وYDT عند الحاجة) عبر مؤسسة القياس ÖSYM$$,
    $$إن كنت في مدرسة سفارة أو مدرسة دولية مُدرَجة في نظام MOBIS أو ضمن مشروع MEB/YÖK، فتحقّق رسمياً من أهليتك لمسار YÖS / TR-YÖS رغم دراستك داخل تركيا$$,
    $$إن أنهيت ثانويتك خارج تركيا فمسارك YÖS / TR-YÖS؛ استخرج معادلة الشهادة (Denklik) من MEB لأنّها لازمة للشهادات غير التركية$$,
    $$راجع نافذة الانتقال بدقّة سنة التسجيل: مَن سُجِّل قبل العام الدراسي 2022-2023 صار YKS فقط من 2026، ومَن سُجِّل من 2022-2023 فصاعداً هو YKS فقط$$,
    $$اطّلع على دليل كل جامعة تستهدفها لمعرفة حصصها (kontenjan) وشروطها والامتحانات البديلة التي تقبلها (SAT / Abitur / IB)$$,
    $$سجّل للامتحان المطلوب في مواعيده الرسمية عبر ÖSYM، ثم تابِع مرحلة التفضيل والتقديم بعد النتيجة$$
  ]::text[],
  ARRAY[
    $$المعيار هو مكان إنهاء الثانوية (داخل/خارج تركيا) لا الجنسية؛ لا يوجد شرط جنسية تركية للتقدّم لـ YKS$$,
    $$تغيير 2026: الأجنبي الذي درس أو تخرّج من الثانوية داخل تركيا لم يعد يُقبل في حصص YÖS/TR-YÖS وصار مساره YKS$$,
    $$استثناء جوهري: طلاب مدارس السفارات، والمدارس الدولية المُدرَجة في MOBIS، وطلاب مشروع MEB/YÖK يبقون مؤهّلين لـ YÖS رغم دراستهم داخل تركيا — تحقّق رسمياً من أهليتك$$,
    $$سنة التسجيل هي الفيصل في نافذة الانتقال، والحدّ الفاصل هو العام الدراسي 2022-2023؛ لا تعتمد على كلام عام عن «الدفعات القديمة»$$,
    $$معادلة الشهادة (Denklik) من MEB تلزم فقط للشهادات غير التركية؛ خرّيج الثانوية التركية لا يحتاجها$$,
    $$الحصص والشروط والمواعيد تختلف بين الجامعات وتتغيّر سنوياً؛ تحقّق رسمياً من دليل ÖSYM/YÖK والجامعة قبل أيّ قرار$$
  ]::text[],
  $$تختلف رسوم التسجيل في الامتحانات (YKS من ÖSYM، وTR-YÖS، وامتحانات الجامعات الخاصة بـ YÖS) ورسوم معادلة الشهادة (Denklik) حسب الجهة، وتُحدَّث سنوياً. لا نذكر مبلغاً ثابتاً هنا لأنّ الأرقام تتغيّر كل سنة؛ تحقّق رسمياً من الرقم الحالي على موقع ÖSYM وموقع الجامعة المستهدَفة قبل الدفع.$$,
  $$القاعدة الأساسية (المكان لا الجنسية) والاستثناءات موثّقة من أسس YÖK وÖSYM، لكن الحصص (kontenjan) والشروط والمواعيد والرسوم وقوائم المدارس المشمولة بالاستثناء (مدارس السفارات، مدارس MOBIS، مشاريع MEB) تُراجَع وتُحدَّث سنوياً. لا تبنِ قرارك على هذا المقال وحده؛ تحقّق رسمياً من دليل ÖSYM / YÖK الحالي ومن الجامعة التي تستهدفها قبل التسجيل، خصوصاً إن كنت تستند إلى أحد الاستثناءات أو تقع ضمن نافذة الانتقال.$$,
  $$https://egitim.yok.gov.tr/tr/page/493 | https://www.osym.gov.tr/TR,4661/basvurma-kosullari.html$$,
  $$YKS أم YÖS 2026؟ امتحان الجامعة يُحدّده مكان دراستك الثانوية لا جنسيتك$$,
  $$هل تدخل الجامعة في تركيا عبر YKS أم YÖS؟ المعيار مكان إنهاء الثانوية (داخل/خارج تركيا) لا الجنسية. شرح تغيير 2026، واستثناءات مدارس السفارات وMOBIS ومشروع MEB، ونافذة الانتقال بدقّة سنة التسجيل 2022-2023.$$,
  ARRAY[
    $$YKS أم YÖS$$,
    $$امتحان الجامعة في تركيا للسوريين$$,
    $$الفرق بين YKS و YÖS$$,
    $$دخول الجامعة في تركيا 2026$$,
    $$TR-YÖS$$,
    $$YÖS للطلاب داخل تركيا$$,
    $$مدارس السفارات YÖS$$,
    $$MOBIS المدارس الدولية تركيا$$,
    $$معادلة الشهادة الثانوية MEB$$,
    $$نافذة الانتقال YKS 2022-2023$$,
    $$TYT AYT YDT$$,
    $$القبول من الخارج YÖK$$
  ]::text[],
  ARRAY[
    $$التعليم والجامعات$$,
    $$YKS$$,
    $$YÖS$$,
    $$TR-YÖS$$,
    $$الجامعات في تركيا$$,
    $$معادلة الشهادة$$,
    $$الطلاب السوريون في تركيا$$,
    $$2026$$
  ]::text[],
  'pending', true, '2026-07-04', '2026-07-04'
) ON CONFLICT (id) DO NOTHING;
